    button:disabled { opacity: .6; }
  </style>
</head>
<body>
  <main>
    <h1>Mini Task Manager</h1>
    <div id="error-box" class="error" role="alert" aria-live="assertive"></div>
    <form id="create-form">
      <label for="new-title">New Task</label>
      <input id="new-title" type="text" placeholder="New task title..." required>
      <button id="create-submit" type="submit">Add Task</button>
    </form>
    <div class="controls">
      <label for="search-q">Search</label><input id="search-q" type="search" placeholder="Search tasks...">
      <label for="filter-status">Status</label>
      <select id="filter-status">
        <option value="">All Statuses</option><option value="todo">Todo</option>
        <option value="in_progress">In Progress</option><option value="done">Done</option>
      </select>
      <button id="search-btn" type="button">Filter</button>
      <button id="retry-btn" type="button" hidden>Retry loading tasks</button>
