    <div id="task-list" aria-busy="false"></div>
  </main>
  <script>
    const byId = id => document.getElementById(id);
    let listSequence = 0;
    let listController = null;

    function errorMessage(data, fallback) {
      if (typeof data === 'string') return data || fallback;
      if (typeof data?.detail === 'string') return data.detail;
      if (Array.isArray(data?.detail)) {
        return data.detail.map(item => {
          const field = Array.isArray(item.loc) ? item.loc.filter(part => part !== 'body').join('.') : '';
          return (field ? field + ': ' : '') + (item.msg || 'Invalid value');
        }).join('; ');
      }
      return fallback;
    }

    async function requestJson(url, options = {}) {
      let response;
      try { response = await fetch(url, options); }
      catch (error) {
        if (error.name === 'AbortError') throw error;
        throw new Error('Network error. Check the connection and retry. Your input has been kept.');
      }
      if (!response.ok) {
        let data = null;
        try { data = await response.json(); } catch (_) { /* HTTP error may be HTML. */ }
        throw new Error(errorMessage(data, 'Request failed (HTTP ' + response.status + '). Please retry.'));
      }
      if (response.status === 204) return null;
      try { return await response.json(); }
      catch (_) { throw new Error('The server returned an invalid response. Please retry.'); }
    }

    function showError(message) { byId('error-box').textContent = message || ''; }

    async function withBusy(control, action) {
      if (control.disabled) return;
      control.disabled = true;
      showError('');
      try { await action(); await fetchTasks(); }
      catch (error) { showError(error.message); }
      finally { control.disabled = false; }
    }

    function renderTasks(tasks) {
      const list = byId('task-list');
      list.textContent = '';
      tasks.forEach(task => {
        const row = document.createElement('div'); row.className = 'task-item';
        const title = document.createElement('span'); title.className = 'task-title';
        title.textContent = task.title + ' (' + task.status + ')'; row.appendChild(title);
        const actions = document.createElement('div'); actions.className = 'task-actions';
        const status = document.createElement('select');
