        actions.appendChild(remove); row.appendChild(actions); list.appendChild(row);
      });
    }

    async function fetchTasks() {
      const sequence = ++listSequence;
      if (listController) listController.abort();
      listController = new AbortController();
      const signal = listController.signal;
      const query = new URLSearchParams();
      if (byId('search-q').value) query.set('q', byId('search-q').value);
      if (byId('filter-status').value) query.set('status', byId('filter-status').value);
      byId('task-list').setAttribute('aria-busy', 'true');
      byId('list-status').textContent = 'Loading tasks...';
      byId('retry-btn').hidden = true;
      showError('');
      try {
        const tasks = await requestJson('/tasks?' + query.toString(), {signal});
        if (sequence !== listSequence) return;
